exportRecipes.ci21-decision-worker-product.ts:
// SDK da2a4ddb; pnpm install --frozen-lockfile first.
// Replay original engine aeb86d13:test/decision-simulation.test.ts, case SDK worker executes.
// Alias its ../src/sharddev/projectOutput to this wrapper; nameBlob to the pinned SDK, compileScript through the source-keyed guest export recipe.
// The original fixture() and beforeAll define the exact shard, Wasm and arguments; preserve native Maps/bytes over v8 I/O.
import {mergeProjectBlobs as merge} from '<checkouts>/sharddev/src/sharddev/projectOutput.ts';
import {writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
export function mergeProjectBlobs(...args:Parameters<typeof merge>){
 const inputSha256=createHash('sha256').update(JSON.stringify(args[0])).digest('hex');
 const result=merge(...args);
 writeFileSync('tmp/codex-tc48/decision-worker-folder.json',JSON.stringify({inputSha256,sourceCommit:'da2a4ddb564db35b5c3bcba4ba1358de92ced1af',shard:result.shard,assets:[...result.assets].map(([hash,bytes])=>[hash,Buffer.from(bytes).toString('base64')])})+'\n');
 return result;
}

exportRecipes.export-scene-graphs.mjs:
import {writeFileSync} from 'node:fs';
import {worldSceneGraphPages} from '../../src/sharddev/worldScenes.ts';
import {parseWorldSceneWeld} from '@wildshard/format/worldSceneWeld';
import {parseWorldSceneModels} from '@wildshard/format/worldSceneModels';
const graph=name=>parseWorldSceneWeld({id:name,root:'root',nodes:[{kind:'group',id:'shared',parent:'root'},{kind:'light',id:'light',parent:'shared',color:1,intensity:1,distance:1,decay:2}]});
const expected=[graph('phone'),graph('desktop')],pages=worldSceneGraphPages('specimens','weld',expected.map((row,i)=>({name:String(i),row}))),blob=pages.files[0];
if(blob===undefined)throw new Error('Missing native graph page');
const references=[...pages.references.values()];
const catalogue=parseWorldSceneModels({product:'page-contract',models:[{key:'model',id:'page-contract/model',name:'Model',file:'source',category:'props',pipeline:'code',defaults:{},variants:[],assembly:'scene',choices:[{id:'only',params:{},size:[1,1,1],draws:[],colliders:[],scene:{phone:references[0],desktop:references[1]}}]}]});
writeFileSync('tmp/codex-tc48/sdk-scene-graphs.json',JSON.stringify({name:blob.file.name,wire:new TextDecoder().decode(blob.bytes),catalogue,expected})+'\n');
